source2='''from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            out.append((color, cells))
    return out


def l_corner(cells):
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    for r in (r0, r1):
        for c in (c0, c1):
            expected = {(y, c) for y in range(r0, r1 + 1)} | {(r, x) for x in range(c0, c1 + 1)}
            if set(cells) == expected:
                return r, c
    return None


def transform(grid):
    grid = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs = components(grid)
    keys = []
    for color, cells in objs:
        corner = l_corner(cells)
        if color != bg and corner is not None:
            rs = [r for r, _ in cells]
            cs = [c for _, c in cells]
            keys.append((color, cells, corner, (min(rs), max(rs), min(cs), max(cs))))
    if not keys:
        return grid
    key_color, key_cells, (er, ec), (r0, r1, c0, c1) = max(keys, key=lambda item: len(item[1]))
    vertical_up = er == r1
    horizontal_left = ec == c1
    height, width = r1-r0+1, c1-c0+1

    # Usually the target lies across the horizontal stroke. For the up-left
    # corner, the longer stroke determines which side contains that object.
    if vertical_up and horizontal_left:
        target_right = width > height
        strict_vertical = True
        target_below = True
        largest_first = True
    elif not vertical_up and horizontal_left:
        target_right = True
        strict_vertical = True
        target_below = False
        largest_first = True
    else:
        target_right = False
        strict_vertical = False
        target_below = vertical_up
        largest_first = False

    candidates = []
    for color, cells in objs:
        if color == bg or cells == key_cells:
            continue
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        if target_right:
            if min(cs) <= ec:
                continue
            horizontal_gap = min(cs) - ec
        else:
            if max(cs) >= ec:
                continue
            horizontal_gap = ec - max(cs)
        if strict_vertical:
            if target_below and min(rs) <= er:
                continue
            if not target_below and max(rs) >= er:
                continue
            vertical_gap = min(rs)-er if target_below else er-max(rs)
        else:
            if target_below and max(rs) < er:
                continue
            if not target_below and min(rs) > er:
                continue
            vertical_gap = max(0, min(rs)-er) if target_below else max(0, er-max(rs))
        candidates.append((color, cells, len(cells), vertical_gap, horizontal_gap))

    if not candidates:
        return grid
    if largest_first:
        _, target_cells, _, _, _ = min(candidates, key=lambda x: (-x[2], x[4], x[3]))
    else:
        _, target_cells, _, _, _ = min(candidates, key=lambda x: (x[3], x[4], -x[2]))
    for r, c in target_cells:
        grid[r][c] = key_color
    return grid
'''
